package com.pollhub.service;
import com.pollhub.dto.VoteRequest;import com.pollhub.entity.*;import com.pollhub.exception.BusinessRuleException;import com.pollhub.repository.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.time.LocalDateTime;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class VoteServiceTest{@Mock VoteRepository votes;@Mock PollRepository polls;@Mock PollOptionRepository options;@Mock UserRepository users;@InjectMocks VoteService service;Poll poll;User user;PollOption option;
 @BeforeEach void setup(){poll=new Poll();poll.setId(1L);poll.setActive(true);poll.setExpiresAt(LocalDateTime.now().plusHours(1));user=new User();user.setId(2L);user.setEmail("u@test.rs");option=new PollOption();option.setId(3L);option.setPoll(poll);when(polls.findById(1L)).thenReturn(Optional.of(poll));}
 @Test void createsVote(){when(users.findByEmail(user.getEmail())).thenReturn(Optional.of(user));when(options.findByIdAndPollId(3L,1L)).thenReturn(Optional.of(option));when(votes.saveAndFlush(any())).thenAnswer(i->{Vote v=i.getArgument(0);v.setId(4L);return v;});assertEquals(3L,service.vote(1L,new VoteRequest(3L),user.getEmail()).optionId());}
 @Test void rejectsDuplicate(){when(users.findByEmail(user.getEmail())).thenReturn(Optional.of(user));when(votes.existsByUserIdAndPollId(2L,1L)).thenReturn(true);assertThrows(BusinessRuleException.class,()->service.vote(1L,new VoteRequest(3L),user.getEmail()));}
 @Test void rejectsExpiredPoll(){poll.setExpiresAt(LocalDateTime.now().minusMinutes(1));assertThrows(BusinessRuleException.class,()->service.vote(1L,new VoteRequest(3L),user.getEmail()));}
}
